css:
/* From Uiverse.io by satyamchaudharydev - Tags: input, search */
/* this is a recreation of twitter search in css */
.__UIV_SCOPE__ .form {
  --input-text-color: #fff;
  --input-bg-color: #283542;
  --focus-input-bg-color: transparent;
  --text-color: #949faa;
  --active-color: #1b9bee;
  --width-of-input: 200px;
  --inline-padding-of-input: 1.2em;
  --gap: 0.9rem;
}
/* form style */
.__UIV_SCOPE__ .form {
  font-size: 0.9rem;
  display: flex;
  gap: 0.5rem;
  align-items: center;
  width: var(--width-of-input);
  position: relative;
  isolation: isolate;
}
/* a fancy bg for showing background and border when focus. */
.__UIV_SCOPE__ .fancy-bg {
  position: absolute;
  width: 100%;
  inset: 0;
  background: var(--input-bg-color);
  border-radius: 30px;
  height: 100%;
  z-index: -1;
  pointer-events: none;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
}
/* label styling */
.__UIV_SCOPE__ label {
  width: 100%;
  padding: 0.8em;
  height: 40px;
  padding-inline: var(--inline-padding-of-input);
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .search,.__UIV_SCOPE__ .close-btn {
  position: absolute;
}
/* styling search-icon */
.__UIV_SCOPE__ .search {
  fill: var(--text-color);
  left: var(--inline-padding-of-input);
}
/* svg -- size */
.__UIV_SCOPE__ svg {
  width: 17px;
  display: block;
}
/* styling of close button */
.__UIV_SCOPE__ .close-btn {
  border: none;
  right: var(--inline-padding-of-input);
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  padding: 0.1em;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--active-color);
  opacity: 0;
  visibility: hidden;
}
/* styling of input */
.__UIV_SCOPE__ .input {
  color: var(--input-text-color);
  width: 100%;
  margin-inline: min(2em,calc(var(--inline-padding-of-input) + var(--gap)));
  background: none;
  border: none;
}

.__UIV_SCOPE__ .input:focus {
  outline: none;
}

.__UIV_SCOPE__ .input::placeholder {
  color: var(--text-color)
}
/* input background change in focus */
.__UIV_SCOPE__ .input:focus ~ .fancy-bg {
  border: 1px solid var(--active-color);
  background: var(--focus-input-bg-color);
}
/* search icon color change in focus */
.__UIV_SCOPE__ .input:focus ~ .search {
  fill: var(--active-color);
}
/* showing close button when typing */
.__UIV_SCOPE__ .input:valid ~ .close-btn {
  opacity: 1;
  visibility: visible;
}
/* this is for the default background in input,when selecting autofill options -- you can remove this code if you do not want to override the browser style.  */
.__UIV_SCOPE__ input:-webkit-autofill,
.__UIV_SCOPE__ input:-webkit-autofill:hover,
.__UIV_SCOPE__ input:-webkit-autofill:focus,
.__UIV_SCOPE__ input:-webkit-autofill:active {
  -webkit-transition: "color 9999s ease-out, background-color 9999s ease-out";
  -webkit-transition-delay: 9999s;
}
